sys_script_include.script:
var PrefillVariables = Class.create();
PrefillVariables.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    loadVariablesFromItem: function() {
        var ritmId = this.getParameter('sysparm_ritm_id');
        var result = {};
        var mtomGR = new GlideRecord('sc_item_option_mtom');
        mtomGR.addQuery('request_item', ritmId);
        mtomGR.query();
        // 动态取得 request item 表里面的变量。
        while (mtomGR.next()) {
            try {
                var varGr = mtomGR.getElement('sc_item_option');
                var optGR = varGr.getRefRecord();
                var optId = optGR.getValue('item_option_new');
                var optGRNew = new GlideRecord('item_option_new');
                if (optGRNew.get(optId)) {
                    // 动态取得变量的名字
                    var name = optGRNew.getValue('name');
                    result[name] = varGr.value.toString();
                }
            } catch (e) {
                gs.info("catch e===============" + e.message);
            }
        }
        result['resubmit_id'] = ritmId;
        var ritm = new GlideRecord('sc_req_item');
        if (ritm.get(ritmId)) {
			// 在画面上添加一个Resubmit的提示信息
            result['tips'] = ritm.number + ' Resubmit Operation';
        }
        // 将变量和值返回画面
        return JSON.stringify(result);
    },
    type: 'PrefillVariables'
});
